// Scratch direct actual Prepare/ProjectAlgebraic/Diagnose nonlinear norm audit.
#include "projected_base.hpp"
int main(int argc,char**argv){Kokkos::ScopeGuard guard(argc,argv);try{Audit a(16,2.2,1e-4);size_t N=a.cells.size(),dim=20*N;std::vector<double>v(dim);auto D=a.patch.Diagnose(a.base);std::cout<<std::setprecision(17)<<"{\"points\":"<<N<<",\"reference_H_M_Z\":["<<D.h_l2<<','<<D.m_l2<<','<<D.z_l2<<"]}\n"<<std::flush;double scale;while(std::cin.read(reinterpret_cast<char*>(&scale),8)&&std::cin.read(reinterpret_cast<char*>(v.data()),dim*8)){double vmax=0;for(double x:v)vmax=std::max(vmax,std::abs(x));double eps=scale/std::max(vmax,1e-300),out[6]{};int signidx=0;for(int sign:{1,-1}){Kokkos::deep_copy(a.q,a.base);for(size_t p=0;p<N;++p){const auto&c=a.cells[p];double raw[22];Lift(v.data()+20*p,c,raw);for(int f=0;f<22;++f)a.q(0,f,c.k,c.j,c.i)+=sign*eps*raw[f];}a.patch.ProjectAlgebraic(a.q);auto diag=a.patch.Diagnose(a.q);out[3*signidx]=diag.h_l2/eps;out[3*signidx+1]=diag.m_l2/eps;out[3*signidx+2]=diag.z_l2/eps;++signidx;}std::cout.write(reinterpret_cast<char*>(out),sizeof(out));std::cout.flush();}}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
